hugo (sdk): TypeScript (iterator + resume helper):

```ts
// TS — iterator + resume
import Redwood from '@redwood/inference'
const client = new Redwood()

export async function* pagesWithRetry(prompt: string) {
  for await (const s of client.streamResponses({ model: 'open-3', input: prompt })) {
    try { for await (const p of s.paginate()) yield p }
    catch {
      const token = (s as any).retryToken
      const cursor = await client.getCursorFromRetry(token)
      for await (const p of client.resumePages(cursor)) yield p
    }
  }
}
```

anya (eng): Go SDK uses ResumeStream(cursor) pattern — include that.

hugo (sdk): Go example (resume stream):

```go
// Go — resume stream
st, _ := client.StreamResponses(ctx, params)
for st.Next() {
  pages, err := st.Pages()
  if err != nil {
    token, _ := st.RetryToken()
    cur, _ := client.GetCursorFromRetry(ctx, token)
    resumed := client.ResumeStream(ctx, cur)
    for resumed.Next() { for _, p := range resumed.Pages() { out <- p } }
    return
  }
  for _, p := range pages { out <- p }
}
```

